#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <cctype>
#include <algorithm>
#include <climits>
using namespace std;

using ll = long long;
const int INF = 0x3f3f3f3f;
const int MAX_NODES = 210;

struct Edge {
    int to, cap, rev;
    Edge(int t, int c, int r) : to(t), cap(c), rev(r) {}
};

vector<Edge> graph[MAX_NODES];
int level[MAX_NODES], iter[MAX_NODES];

void add_edge(int from, int to, int capacity) {
    graph[from].emplace_back(to, capacity, graph[to].size());
    graph[to].emplace_back(from, 0, graph[from].size() - 1);
}

void bfs(int s) {
    memset(level, -1, sizeof(level));
    queue<int> q;
    level[s] = 0;
    q.push(s);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (const auto& e : graph[u]) {
            if (e.cap > 0 && level[e.to] < 0) {
                level[e.to] = level[u] + 1;
                q.push(e.to);
            }
        }
    }
}

int dfs(int u, int t, int f) {
    if (u == t) return f;
    for (int& i = iter[u]; i < (int)graph[u].size(); ++i) {
        Edge& e = graph[u][i];
        if (e.cap > 0 && level[u] < level[e.to]) {
            int d = dfs(e.to, t, min(f, e.cap));
            if (d > 0) {
                e.cap -= d;
                graph[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

int max_flow(int s, int t) {
    int flow = 0;
    while (true) {
        bfs(s);
        if (level[t] < 0) return flow;
        memset(iter, 0, sizeof(iter));
        int f;
        while ((f = dfs(s, t, INF)) > 0) flow += f;
    }
}

const int DIRS[4][2] = {{0,1},{0,-1},{1,0},{-1,0}};

int n, T, source, sink;
int cap_grid[15][15], sci_grid[15][15], maze[65][15][15];
bool visited[15][15];
bool reach[65][15][15][15][15];

int get_id(int x, int y, int k) {
    return (x-1)*n + y + k*n*n;
}

void dfs_reach(int sx, int sy, int x, int y, int step) {
    visited[x][y] = true;
    reach[step][sx][sy][x][y] = true;
    if (step >= T || maze[step][x][y]) return;
    for (int d = 0; d < 4; ++d) {
        int nx = x + DIRS[d][0], ny = y + DIRS[d][1];
        if (nx < 1 || ny < 1 || nx > n || ny > n) continue;
        if (visited[nx][ny] || maze[step][nx][ny]) continue;
        dfs_reach(sx, sy, nx, ny, step + 1);
    }
}

void preprocess() {
    for (int t = 1; t <= T; ++t) {
        for (int x = 1; x <= n; ++x) {
            for (int y = 1; y <= n; ++y) {
                if (maze[t-1][x][y]) {
                    maze[t][x][y] = maze[t-1][x][y];
                } else {
                    for (int d = 0; d < 4; ++d) {
                        int nx = x + DIRS[d][0], ny = y + DIRS[d][1];
                        if (nx < 1 || ny < 1 || nx > n || ny > n) continue;
                        if (maze[t-1][nx][ny] == 2) {
                            maze[t][x][y] = 2;
                            break;
                        }
                    }
                }
            }
        }
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (sci_grid[i][j]) {
                memset(visited, 0, sizeof(visited));
                dfs_reach(i, j, i, j, 0);
            }
        }
    }
    for (int t = 1; t <= T; ++t) {
        for (int x = 1; x <= n; ++x) {
            for (int y = 1; y <= n; ++y) {
                for (int xx = 1; xx <= n; ++xx) {
                    for (int yy = 1; yy <= n; ++yy) {
                        reach[t][x][y][xx][yy] |= reach[t-1][x][y][xx][yy];
                    }
                }
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> T;
    for (int i = 1; i <= n; ++i) {
        string s;
        cin >> s;
        for (int j = 1; j <= n; ++j) {
            char c = s[j-1];
            if (isdigit(c)) sci_grid[i][j] = c - '0';
            else if (c == 'Y') maze[0][i][j] = 1;
            else if (c == 'Z') maze[0][i][j] = 2;
        }
    }
    for (int i = 1; i <= n; ++i) {
        string s;
        cin >> s;
        for (int j = 1; j <= n; ++j) {
            char c = s[j-1];
            if (isdigit(c)) cap_grid[i][j] = c - '0';
        }
    }
    source = n*n*2;
    sink = source - 1;
    preprocess();
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (sci_grid[i][j]) add_edge(source, get_id(i,j,0), sci_grid[i][j]);
            if (cap_grid[i][j]) add_edge(get_id(i,j,1), sink, cap_grid[i][j]);
        }
    }
    for (int x = 1; x <= n; ++x) {
        for (int y = 1; y <= n; ++y) {
            for (int xx = 1; xx <= n; ++xx) {
                for (int yy = 1; yy <= n; ++yy) {
                    if (sci_grid[x][y] && cap_grid[xx][yy] && reach[T][x][y][xx][yy]) {
                        add_edge(get_id(x,y,0), get_id(xx,yy,1), INF);
                    }
                }
            }
        }
    }
    cout << max_flow(source, sink) << '\n';
    return 0;
}
